INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'levoit'), 'Core 300', 'levoit-core-300-replacement-filter', 'air_purifier', 'replacement filter for levoit core 300', NULL, 'H13', NULL, NULL, 'Buyers should confirm the exact model designation (e.g., Core 300, Core 300‑P, Core 300S‑P) printed on their unit’s sticker or part number, as listings include filters for multiple Core 300 variants.', '[{"q": "What part code is required for a Levoit Core 300 replacement filter?", "a": "The listings do not provide a specific official part code; customers should reference the part number on their existing filter or unit."}, {"q": "Is there a difference between OEM and third‑party filters for the Core 300?", "a": "OEM filters are made by Levoit, while third‑party replacements (e.g., 2‑pack options) are not; both claim compatibility but OEM guarantees brand‑matched specifications."}, {"q": "What filtration grade and features do the listed replacement filters offer?", "a": "One listing specifies a 3‑in‑1 H13 True HEPA and activated carbon filter; other listings do not state a grade, so features may vary."}]', 'The Levoit Core 300 uses a 3‑in‑1 H13 True HEPA and activated carbon replacement filter; no official filter part code is specified in the listings. Both genuine OEM filters and third‑party multi‑pack options currently sold, widely offering compatible filtration for the Core 300 series today.', '["Fits Levoit Core 300 and related models such as Core 300S, Core 300‑P, and Core P350", "Listings include a 3‑in‑1 H13 True HEPA and activated carbon filter option", "Both OEM filters and third‑party multi‑pack (2‑pack) replacements are available"]', 'published') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
