INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'levoit'), 'Core 400S', 'levoit-core-400s-replacement-filter', 'air_purifier', 'replacement filter for levoit core 400s', 'LRF-C401S-WUS', 'H13', NULL, NULL, 'Buyers should confirm the exact Core 400S model (e.g., Core 400S‑P or Core 400S‑RF) and corresponding part number on the unit’s label before ordering a replacement filter.', '[{"q": "What part code filter fits the Levoit Core 400S?", "a": "The official replacement filter is listed as LRF‑C401S‑WUS, which matches the Core 400S series."}, {"q": "Is there a difference between OEM and third‑party filters?", "a": "OEM filters carry the official part code and are made by Levoit, while third‑party packs offer compatible filters without the OEM designation, often in multi‑pack sizes."}, {"q": "What filtration grade and features do the listed replacements provide?", "a": "Listings mention an H13 HEPA grade and a 3‑in‑1 design that combines pre‑filter, HEPA, and activated carbon layers for comprehensive air cleaning."}]', 'Replacement filters compatible with the Levoit Core 400S are identified by the official part code LRF‑C401S‑WUS and feature an H13 HEPA filtration grade. Both genuine OEM filters and third‑party multi‑pack options are offered, providing choices for standard home replacements or bulk purchases online today now.', '["Filters with part code LRF‑C401S‑WUS and H13 HEPA grade are compatible with Levoit Core 400S.", "Both OEM (official code) and third‑party multi‑pack options appear in listings.", "Variants include Core 400S‑P, Core 400S‑RF, and 3‑in‑1 H13 models, so verify exact model before purchase."]', 'published') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'levoit'), 'Vital 200S P', 'levoit-vital-200s-p-replacement-filter', 'air_purifier', 'replacement filter for levoit vital 200s p', NULL, 'H13', NULL, NULL, 'Verify your specific unit is a Levoit Vital 200S-P, Vital 200S, or Vital 200S-RF, as these are the only variants confirmed compatible in the listings. Do not assume compatibility with other Levoit models without checking the model sticker.', '[{"q": "What filter part number fits the Levoit Vital 200S P?", "a": "The specific alphanumeric part number is not explicitly stated in the provided listings, but the filter is identified as the ''Vital 200S Replacement Filter'' compatible with the Vital 200S-P model."}, {"q": "Is there a difference between OEM and third-party filters for this model?", "a": "OEM filters are manufactured by Levoit and labeled as ''Genuine,'' while third-party options are labeled as ''Replacement'' and often sold in 2-packs. Both are listed as compatible with the Vital 200S-P."}, {"q": "What filtration technology does the Vital 200S P filter use?", "a": "The listings specify that the replacement filters utilize H13 True HEPA and high-efficiency activated carbon filtration."}]', 'The Levoit Vital 200S P utilizes a replacement filter compatible with the Vital 200S and Vital 200S-RF models. Listings confirm H13 True HEPA and high-efficiency activated carbon filtration capabilities. Both genuine Levoit OEM filters and third-party multi-pack replacements are available for purchase, ensuring consistent air purification performance for this specific air purifier unit.', '["Filters are cross-compatible with Levoit Vital 200S, Vital 200S-P, and Vital 200S-RF models.", "Listed filters feature H13 True HEPA and high-efficiency activated carbon filtration.", "Buyers can choose between single genuine OEM filters or third-party 2-pack value options."]', 'published') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
