re available for purchase."]', 'published') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'levoit'), 'H128', 'levoit-h128-replacement-filter', 'air_purifier', 'levoit replacement filter for h128', 'LV-H128', NULL, NULL, NULL, 'Verify your exact Levoit H128 model sticker or part number before ordering, as listings indicate compatibility with variants like LV-H128-RF and specific third-party models (PUURVSAS HM669A, ROVACS RV60). Ensure the filter code matches your device''s requirements to avoid fitment issues.', '[{"q": "What is the correct filter part number for the Levoit H128?", "a": "The correct filter part number is LV-H128. Some listings also reference LV-H128-RF, indicating a specific variant or revision of the filter."}, {"q": "Are there OEM and third-party options for the Levoit H128 filter?", "a": "Yes, genuine Levoit OEM filters are available, as well as third-party replacements. Third-party options include multi-packs such as 4-packs and 8-packs, which may offer better value for frequent replacements."}, {"q": "Does the LV-H128 filter fit other air purifier brands?", "a": "According to the listings, the LV-H128 filter is compatible with PUURVSAS (HM669A) and ROVACS (RV60) air cleaners, in addition to Levoit LV-H128 models."}]', 'The Levoit H128 air purifier utilizes the LV-H128 replacement filter. While specific HEPA grades are not explicitly detailed in the provided listings, the filter is identified by the part code LV-H128. Consumers can choose between genuine Levoit OEM filters and third-party multi-pack replacements, such as 4-packs or 8-packs, which offer cost-effective alternatives for maintaining air quality in compatible Levoit units.', '["The specific filter part number for the Levoit H128 is LV-H128, with some listings also referencing LV-H128-RF.", "Both genuine Levoit OEM filters and third-party replacement packs (4-pack and 8-pack) are available for this model.", "The LV-H128 filter is compatible with Levoit LV-H128 air purifiers, as well as specific models from PUURVSAS and ROVACS."]', 'published') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
