INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'winix'), '5520', 'winix-5520-replacement-filter', 'air_purifier', 'replacement filter for winix 5520', '1712-0123-00', 'H13 True HEPA', NULL, NULL, 'Verify the exact model and part number on your Winix 5520 unit before ordering, as some listings also cover 5510 and 5530 variants which may use the same code but differ in packaging or accessories.', '[{"q": "What is the correct replacement filter part number for a Winix 5520?", "a": "The official replacement filter for the Winix 5520 is part number 1712-0123-00, which is listed on the unit and matches the HEPA‑Carbon filter sold on Amazon."}, {"q": "Is there a difference between OEM Winix filters and third‑party replacements?", "a": "OEM filters are labeled as genuine Winix and guarantee factory specifications, while third‑party filters use the same part number but may be sold in multi‑packs and lack the Winix branding."}, {"q": "What filtration performance does the 1712-0123-00 filter provide?", "a": "It combines an H13 True HEPA element with activated carbon, delivering high‑efficiency particle capture and odor reduction for the Winix 5520 air purifier."}]', 'The Winix 5520 air purifier uses filter model 1712-0123-00, a H13 True HEPA cartridge with activated carbon. Both genuine Winix OEM filters and multi‑pack third‑party replacements are sold, offering the same part number and filtration performance for the 5520 unit, ensuring reliable, compatible maintenance throughout.', '["The filter part number 1712-0123-00 fits Winix 5520 (and 5510, 5530) models.", "It is a H13 True HEPA filter combined with activated carbon for odor control.", "Buyers can choose OEM genuine Winix filters or lower‑cost multi‑pack third‑party replacements."]', 'enriched') ON CONFL