INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), 'HEV615 And HEV620 Humidifiers', 'honeywell-hev615-and-hev620-humidifiers-replacement-filter', 'air_purifier', 'replacement filter for honeywell hev615 and hev620 humidifiers', 'HFT600', NULL, NULL, NULL, 'Buyers should confirm that their humidifier is the Honeywell HEV615 or HEV620 series and check the model sticker or part number, as the listings reference the HFT600 T filter for these specific models. Some listings also note the filter is sold in multi‑pack quantities, so ensure the correct quantity for your unit.', '[{"q": "What part number filter fits Honeywell HEV615 and HEV620 humidifiers?", "a": "The compatible filter is the HFT600 model T wicking filter, as indicated in the product titles."}, {"q": "Is there a difference between OEM Honeywell filters and third‑party replacements?", "a": "OEM filters are manufactured by Honeywell and listed as Honeywell HFT600, while third‑party options like Lemige are compatible replacements sold in multi‑pack sizes but are not Honeywell‑branded."}, {"q": "Do these filters have a HEPA rating or special filtration features?", "a": "The titles do not specify a HEPA grade; they describe a wicking filter type without additional filtration ratings."}]', 'Replacement filters for Honeywell HEV615 and HEV620 humidifiers use the HFT600 wicking filter model T. The listings show both Honeywell‑branded OEM units and third‑party multi‑pack options. No specific HEPA grade is indicated, and the filters are sold in packs ranging from three to six units.', '["The HFT600 T wicking filter is compatible with both HEV615 and HEV620 humidifier models.", "Filters are wicking type with no HEPA grade specified in the titles.", "Both OEM Honeywell parts and third‑party multi‑pack options (3‑6 count) are available."]', 'published') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
