INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'blueair'), '311I Max', 'blueair-311i-max-replacement-filter', 'air_purifier', 'replacement filter for blueair 311i max', NULL, NULL, NULL, NULL, 'Before purchasing, confirm the exact Blueair 311I Max model sticker or part number, as some listings reference the AllergenBlock variant and may not match all 311I Max configurations.', '[{"q": "What is the official filter part code for the Blueair 311I Max?", "a": "The titles do not list an official part code; OEM filters are identified by the ''BLUEAIR Genuine'' label."}, {"q": "Are the 2‑pack AllergenBlock filters OEM or third‑party?", "a": "They are third‑party replacements, not manufactured by Blueair."}, {"q": "What filtration features are mentioned for the replacement filters?", "a": "The AllergenBlock filter includes premium activated carbon and is marketed as an allergen‑blocking replacement, while OEM filters are described simply as genuine replacements."}]', 'The Blueair 311I Max uses a specific replacement filter; official OEM filters are labeled ''BLUEAIR Genuine'' but no part code is listed in the titles. Third‑party options include multi‑pack replacements such as the 2‑pack AllergenBlock filter. Both OEM and value packs are available for use.', '["OEM filters are labeled ''BLUEAIR Genuine'' and fit the 311I Max.", "Third‑party replacements come in multi‑pack options such as the 2‑pack AllergenBlock filter.", "No explicit part code or dimensions are listed in the titles; buyers should verify model compatibility."]', 'published') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=exclu