INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'blueair'), 'Blue Pure 411', 'blueair-blue-pure-411-replacement-filter', 'air_purifier', 'replacement filter for blueair blue pure 411', NULL, NULL, NULL, NULL, 'Buyers should confirm the exact Blueair Blue Pure 411 model and part number on their unit’s label before purchasing, as listings include filters for 411, 411+, and 411 Auto variants.', '[{"q": "What official part code is required for a Blueair Blue Pure 411 replacement filter?", "a": "The product titles do not list a specific official part code; customers should check the label on their unit for the correct code."}, {"q": "Are OEM (Blueair) filters different from third‑party replacements for the Blue Pure 411?", "a": "OEM filters are labeled as Blueair genuine and are made by the manufacturer, while third‑party filters are compatible replacements without Blueair branding; performance and warranty may differ."}, {"q": "What filtration grade or maintenance schedule applies to these replacement filters?", "a": "No HEPA grade or dimensions are mentioned in the titles; users should follow Blueair’s typical recommendation to replace the filter about every six months or according to usage."}]', 'Replacement filters compatible with the Blueair Blue Pure 411 air purifier are sold under various listings; no specific official part code or HEPA grade is disclosed in the titles. Both Blueair‑genuine (OEM) filters and third‑party multi‑pack replacements are offered, fitting the 411, 411+, and 411 Auto models.', '["Fits Blueair Blue Pure 411, 411+, and 411 Auto air purifiers.", "Listings do not disclose HEPA grade, filter shape, or exact dimensions.", "Both Blueair‑genuine OEM filters and third‑party multi‑pack replacements are sold."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'blueair'), 'Blue Pure 211+ Air Purifiers', 'blueair-blue-pure-211-air-purifiers-replacement-filter', 'air_purifier', 'replacement filter for blueair blue pure 211+ air purifiers', NULL, 'H13', NULL, '{"length_in": 3.3, "width_in": 20.8, "height_in": 12.3}', 'Verify your specific unit is a Blue Pure 211+ or 211+ Auto, as listings distinguish between these variants. Ensure the filter type (e.g., AllergenBlock vs. Everyday) matches your maintenance needs and model sticker.', '[{"q": "What is the official filter part code for the Blueair Blue Pure 211+?", "a": "The provided listings do not explicitly state an official alphanumeric part code, but identify the filters as ''Genuine 211+ Air Purifier Replacement Filter'' and ''AllergenBlock Filter''."}, {"q": "What is the difference between OEM and third-party filters for this model?", "a": "OEM filters are manufactured by Blueair and labeled as ''Genuine,'' while third-party options are ''Compatible'' replacements that may offer multi-packs and specify H13 True HEPA and activated carbon filtration."}, {"q": "What filtration features are mentioned for the Blue Pure 211+ replacement filters?", "a": "Listings mention a 2-stage filtration system consisting of H13 True HEPA and activated carbon, with specific variants targeting allergies, pet dander, pollen, and dust."}]', 'The Blueair Blue Pure 211+ Air Purifier uses a genuine replacement filter, with the AllergenBlock variant measuring 3.3" x 20.8" x 12.3". Listings indicate a 2-stage filtration system featuring H13 True HEPA and activated carbon. Both official Blueair OEM filters and third-party compatible multi-packs are available for this specific air purifier series.', '["Genuine Blueair filters are available for the 211+ and 211+ Auto models, including specific AllergenBlock and Everyday variants.", "Third-party options offer 2-stage filtration with H13 True HEPA and activated carbon, often in 2-packs.", "The AllergenBlock filter has specified dimensions of 3.3\" x 20.8\" x 12.3\", while other variants do not list explicit measurements in the title."]', 'published') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
