INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'blueair'), 'Replacement Air Blue 3250I', 'blueair-replacement-air-blue-3250i-replacement-filter', 'air_purifier', 'blueair replacement air filter for blue 3250i', NULL, 'H13', NULL, NULL, 'Verify the exact model number and part number on your Blueair Replacement Air Blue 3250I unit before ordering, as some listings target other Blueair series such as 511i or 200/300 models.', '[{"q": "What part code filter fits the Blueair Replacement Air Blue 3250I?", "a": "The listings do not specify an official part code; buyers should match the model “Blue Max 3250i” or “Blueair 3250” when selecting a filter."}, {"q": "Are OEM filters different from third‑party replacements?", "a": "OEM filters are manufactured by Blueair and labeled “Genuine,” while third‑party filters are made by other brands; both claim H13 True HEPA performance but OEM guarantees exact brand compatibility."}, {"q": "What filtration performance and maintenance do these filters offer?", "a": "The compatible filters are described as H13 True HEPA with activated carbon, providing high‑efficiency particle capture; they are sold in single or multi‑pack sizes and should be replaced according to the manufacturer’s recommended interval."}]', 'Replacement filters that fit the Blueair Replacement Air Blue 3250I are available as both OEM parts and third‑party multi‑pack options. While no specific official filter part code appears in the listings, compatible filters are described as H13 True HEPA with activated carbon. Buyers can choose genuine Blueair units or value‑pack alternatives.', '["Compatibility: Filters labeled for Blueair Blue Max 3250i (e.g., H13 True HEPA) fit the Replacement Air Blue 3250I.", "Filtration: Available filters provide H13 True HEPA and activated carbon filtration.", "Buying options: Both OEM genuine Blueair filters and third‑party multi‑pack replacements are sold."]', 'published') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
