ter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
