INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'dyson'), 'AM11', 'dyson-am11-replacement-filter', 'vacuum', 'replacement filter for dyson am11', 'TP02', 'True HEPA', NULL, NULL, 'Ensure the filter matches the exact Dyson AM11 model number shown on your unit, as some listings also list TP01 or other variants that are not suitable for the AM11 HEPA stage.', '[{"q": "What filter code fits the Dyson AM11?", "a": "The AM11 uses the TP02 filter, often referenced with part number 968126‑03 and classified as a True HEPA filter."}, {"q": "Are OEM filters different from third‑party replacements?", "a": "OEM filters are made by Dyson and carry the Dyson brand, while third‑party filters use the same TP02 code but are produced by other manufacturers and may be sold in multi‑pack value sets."}, {"q": "What filtration performance and maintenance does the TP02 provide?", "a": "TP02 is a True HEPA filter that captures fine particles; it is typically replaced every 6‑12 months depending on usage, and both OEM and third‑party versions require the same replacement interval."}]', 'Replacement filters for the Dyson AM11 are identified by the TP02 code and are rated as True HEPA. Both genuine Dyson OEM filters and third‑party multi‑pack options are sold, offering the same part number compatibility while differing in branding and packaging, and typically come in convenient two‑filter packs for extended service intervals.', '["TP02 (True HEPA) is the compatible filter for Dyson AM11.", "Listings show both OEM and third‑party multi‑pack options, with TP02 code and part # 968126‑03 referenced.", "Buyers can choose single or 2‑pack sizes, but must verify model number."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=