al_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'dyson'), 'Ball Animal 3', 'dyson-ball-animal-3-replacement-filter', 'vacuum', 'replacement filter for dyson ball animal 3', '920769-01, 920640-01', 'HEPA', NULL, NULL, 'Before purchasing, confirm the exact Dyson Ball Animal 3 model and part number on your vacuum’s sticker, as listings also include filters for Ball Animal 2 and other DC series variants.', '[{"q": "What filter part codes are compatible with the Dyson Ball Animal 3?", "a": "The OEM HEPA filters listed use part numbers 920769-01 (post-filter) and 920640-01 (pre-filter); third-party packs do not specify part codes."}, {"q": "Is there a difference between OEM and third-party replacement filters for the Ball Animal 3?", "a": "OEM filters carry Dyson’s official part numbers and HEPA rating, while third-party packs offer compatible filters without guaranteed OEM specifications."}, {"q": "What filtration performance and maintenance should I expect from these replacements?", "a": "HEPA-rated OEM filters capture fine particles, and both OEM and third-party filters are sold as sets of pre- and post-filters that should be replaced according to Dyson’s recommended schedule."}]', 'Replacement filters for the Dyson Ball Animal 3 are available as OEM HEPA units (part numbers 920769-01 and 920640-01) and as third-party multi-pack sets. Both post-filters and pre-filters are offered, providing compatible filtration for the vacuum’s multi-floor performance, ensuring consistent dust capture and maintaining suction efficiency across carpet and hard-floor surfaces.', '["Filters listed cover Dyson Ball Animal 3 along with other Ball Animal models and DC series variants.", "At least one OEM listing specifies HEPA grade with part numbers 920769-01/920640-01; other packs lack grade details.", "Buyers can choose genuine OEM HEPA filters or lower-cost multi-pack third-party replacements."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
