ls.", "Listed products are third-party pre-filters available in 3-pack and 4-pack quantities, offering value over single-unit purchases.", "These filters are cross-compatible with Dyson V7, V8, DC58, and DC59 series, but buyers must verify their specific V6 Animal variant."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
