INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'roborock'), 'Water S7 Maxv Ultra', 'roborock-water-s7-maxv-ultra-replacement-filter', 'vacuum', 'water filter roborock s7 maxv ultra', NULL, NULL, NULL, NULL, 'Verify your specific Roborock model sticker, as listings indicate cross-compatibility between S7 Maxv Ultra and S7 Pro Ultra variants. Ensure the filter is intended for the mop washing dock rather than the main vacuum dustbin.', '[{"q": "What is the official part number for the Roborock Water S7 Maxv Ultra water filter?", "a": "The provided product listings do not explicitly state an official Roborock part number. They identify the components as water filters and high-speed cleaning brushes compatible with the S7 Maxv Ultra and S7 Pro Ultra models."}, {"q": "Are the listed filters OEM or third-party replacements?", "a": "The listed products are third-party replacements. The titles describe them as ''Replacement Parts'' or ''Compatible with'' Roborock models, and none are identified as manufactured by Roborock."}, {"q": "What components are included in the replacement kits for the S7 Maxv Ultra dock?", "a": "The kits include water filters and high-speed cleaning brushes. These components are used for the mop washing and dock self-cleaning functions, with options available as single items or multi-packs."}]', 'Replacement filters for the Roborock Water S7 Maxv Ultra include water filters and high-speed cleaning brushes for the mop washing dock. Listings indicate compatibility with both S7 Maxv Ultra and S7 Pro Ultra models. No official Roborock part code or specific HEPA grade is explicitly stated in the provided product titles. Both single-item and multi-pack third-party replacement kits are available for dock self-cleaning maintenance.', '["Listed filters are compatible with Roborock S7 Maxv Ultra and S7 Pro Ultra vacuum cleaners.", "Available components include water filters and high-speed cleaning brushes specifically for the mop washing and dock self-cleaning system.", "Third-party replacement kits are available in 2-pack and 3-pack configurations, but no official OEM Roborock part numbers are identified in the titles."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'eufy'), 'Homevac Kit For S11', 'eufy-homevac-kit-for-s11-replacement-filter', 'vacuum', 'eufy homevac replacement filter kit for s11', NULL, 'HEPA', NULL, NULL, 'Verify your specific Eufy HomeVac S11 Elite model sticker before ordering, as listings reference compatibility with Laresar and other Eufy variants like the H11. Ensure the filter shape and size match your specific unit, as dimensions are not explicitly listed in the titles.', '[{"q": "What is the official filter part code for the Eufy HomeVac S11 Elite?", "a": "The provided product titles do not explicitly state an official filter part code. They identify the products as compatible replacements for the Eufy HomeVac S11 Elite and Laresar models."}, {"q": "Are these filters OEM or third-party replacements?", "a": "The listed products are third-party replacements. The titles use terms like ''Compatible for'' and ''Replacement,'' indicating they are not manufactured by Eufy."}, {"q": "What filtration features do these replacement filters offer?", "a": "The listings specify that the filters are HEPA vacuum filters. One listing mentions a 3-pack of HEPA filters for similar Eufy models, while others for the S11 Elite do not specify the pack size in the title."}]', 'Replacement filters for the Eufy HomeVac S11 Elite are available as third-party compatible units. Listings indicate HEPA filtration capabilities, though specific official part codes are not explicitly stated in the provided titles. Both single-unit and multi-pack options exist, with some products referencing Laresar compatibility. Buyers should verify exact model specifications to ensure fitment for the S11 Elite variant.', '["Third-party replacement filters are available for the Eufy HomeVac S11 Elite, with some listings noting compatibility with Laresar models.", "Listed products specify HEPA filtration, but exact official filter part numbers and dimensions are not provided in the titles.", "Options include single filters and 5-piece value packs, all identified as compatible replacements rather than OEM parts."]', 'published') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
